# Generated by devtools completion powershell. Load only a script you generated.
function __DevtoolsLiteral($Element) {
    if ($Element -is [Management.Automation.Language.StringConstantExpressionAst]) { return ,@($true, [string]$Element.Value) }
    if ($Element -is [Management.Automation.Language.ExpandableStringExpressionAst] -and $Element.NestedExpressions.Count -eq 0) { return ,@($true, [string]$Element.Value) }
    if ($Element -is [Management.Automation.Language.CommandParameterAst] -and $null -eq $Element.Argument) { return ,@($true, [string]$Element.Extent.Text) }
    return ,@($false, '')
}
function __DevtoolsComplete {
    param($wordToComplete, $commandAst, $cursorPosition)
    try {
        $elements = @($commandAst.CommandElements)
        if ($elements.Count -eq 0) { return }
        $first = __DevtoolsLiteral $elements[0]
        if (-not $first[0]) { return }
        $commandName = [IO.Path]::GetFileName([string]$first[1])
        if ($commandName -notin @('devtools','dvt','devtools.exe','dvt.exe')) { return }
        $words = [Collections.Generic.List[string]]::new()
        $current = ''
        for ($index = 1; $index -lt $elements.Count; $index++) {
            $element = $elements[$index]
            if ($element.Extent.StartOffset -ge $cursorPosition) { break }
            if ($element.Extent.EndOffset -ge $cursorPosition) {
                if ($element.Extent.EndOffset -gt $cursorPosition) {
                    # Parse the literal prefix only. Parsing does not evaluate it.
                    $fragment = $element.Extent.Text.Substring(0, $cursorPosition - $element.Extent.StartOffset)
                    $tokens = $null; $parseErrors = $null
                    $parsed = [Management.Automation.Language.Parser]::ParseInput('devtools ' + $fragment, [ref]$tokens, [ref]$parseErrors)
                    $commands = @($parsed.FindAll({ param($ast) $ast -is [Management.Automation.Language.CommandAst] }, $false))
                    if ($commands.Count -ne 1 -or $commands[0].CommandElements.Count -ne 2) { return }
                    $element = $commands[0].CommandElements[1]
                }
                $literal = __DevtoolsLiteral $element
                if (-not $literal[0]) { return }
                $current = $literal[1]
                break
            }
            $literal = __DevtoolsLiteral $element
            if (-not $literal[0]) { return }
            $words.Add($literal[1])
        }
        $words.Add($current)
        $candidates = [Collections.Generic.List[string]]::new()
        $application = Get-Command -Name $first[1] -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($application -and (Get-Location).Provider.Name -eq 'FileSystem') {
            $start = [Diagnostics.ProcessStartInfo]::new($application.Source)
            $start.Arguments = '__complete --describe'
            $start.WorkingDirectory = (Get-Location).ProviderPath
            $start.UseShellExecute = $false
            $start.CreateNoWindow = $true
            $start.RedirectStandardInput = $true
            $start.RedirectStandardOutput = $true
            $start.RedirectStandardError = $true
            $utf8 = [Text.UTF8Encoding]::new($false)
            $start.StandardOutputEncoding = $utf8
            $start.StandardErrorEncoding = $utf8
            $child = [Diagnostics.Process]::new()
            $child.StartInfo = $start
            try {
                # .NET Framework otherwise writes a BOM when constructing stdin.
                $savedEncoding = [Console]::InputEncoding
                try { [Console]::InputEncoding = $utf8; $started = $child.Start() }
                finally { [Console]::InputEncoding = $savedEncoding }
                if ($started) {
                    $output = $child.StandardOutput.ReadToEndAsync()
                    $diagnostic = $child.StandardError.ReadToEndAsync()
                    $bytes = $utf8.GetBytes(($words -join [string][char]0) + [char]0)
                    if ($bytes.Length -le 65536) { $child.StandardInput.BaseStream.Write($bytes, 0, $bytes.Length) }
                    $child.StandardInput.BaseStream.Flush()
                    $child.StandardInput.Close()
                    if (-not $child.WaitForExit(2000)) { $child.Kill(); $null = $child.WaitForExit(500) }
                    elseif ($child.ExitCode -eq 0 -and $output.Wait(500)) {
                        foreach ($value in ($output.Result -split '\r?\n')) { if ($value -ne '') { $candidates.Add($value) } }
                    }
                }
            } finally { $child.Dispose() }
        }
        foreach ($line in ($candidates | Sort-Object -Unique)) {
            $parts = $line -split "`t", 2
            $value = $parts[0]
            $description = $value
            if ($parts.Count -eq 2 -and $parts[1] -ne '') { $description = $parts[1] }
            $quoted = "'" + $value.Replace("'", "''") + "'"
            [Management.Automation.CompletionResult]::new($quoted, $value, 'ParameterValue', $description)
        }
    } catch { return }
}
Register-ArgumentCompleter -Native -CommandName devtools,dvt,devtools.exe,dvt.exe -ScriptBlock ${function:__DevtoolsComplete}
